CREATE COLUMN TABLE "TEST_AP"."OTSC" ("ID" INTEGER CS_INT NOT NULL , "CODE" NVARCHAR(20) NOT NULL , "Situation" NCLOB MEMORY THRESHOLD 1000, "Locked" NVARCHAR(1) DEFAULT 'N', "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "Category" SMALLINT CS_INT DEFAULT -6 NOT NULL , "CodeOut" NVARCHAR(20), "OutDesc" NCLOB MEMORY THRESHOLD 1000, "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("ID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OTSC_CST_CODE" ON "TEST_AP"."OTSC" ( "CODE" ASC, "Category" ASC )